import { useId } from 'react';

function PasswordField() {
  const descriptionId = useId();

  return (
    <div>
      <label htmlFor="password">Password</label>
      <input id="password" type="password" aria-describedby={descriptionId} />
      <p id={descriptionId}>The password must contain at least 18 characters.</p>
    </div>
  );
}
